"""Assemble the bounded705 supplemental audit without admitting any record."""
from pathlib import Path
import collections,copy,hashlib,itertools,json,re
import sympy as s
from literal_math import parse
from audit_pairs import scalar_sum,canonical,H
from atan_certificate import normalized_tangent
BASE=Path(__file__).resolve().parent

def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()

def main():
 source=BASE/'effective705-input.jsonl';final=BASE/'effective705-final-v3.jsonl';before=list(map(json.loads,source.read_text().splitlines()));after=list(map(json.loads,final.read_text().splitlines()));full={r['problemId']:r for r in map(json.loads,(BASE/'full-source-records.jsonl').read_text().splitlines())};oldDiag=json.loads((BASE/'root-mathematical-opposite-input.json').read_text());pairs=json.loads((BASE/'mathematical-pairs-final-v3.json').read_text());ranks=json.loads((BASE/'mathematical-ranks-final-v3.json').read_text());screen=json.loads((BASE/'root-option-screen-final-v3.json').read_text());patches={p['problemId']:p for f in ['option-patches.json','bracket-option-patches.json','support-option-patches.json']for p in json.loads((BASE/f).read_text())};assert len(patches)==162;assert not pairs['errors'] and not ranks['errors'];assert pairs['inputSHA256']==ranks['inputSHA256']==sha(final)
 pairby={r['problemId']:r for r in pairs['recordsEvidence']};rankby={r['problemId']:r for r in ranks['recordsEvidence']};previousUnsupported={r['problemId']for r in oldDiag['records']if r['status']=='unsupported'};joins=[];tupleChecks=[];atanChecks=[]
 for old,new in zip(before,after):
  assert old['problemId']==new['problemId'];p=patches.get(old['problemId']);original=full[old['problemId']]
  if p:
   assert p['sourceRawSHA256']==H(original) and p['sourceContentHash']==original['contentHash'] and p['sourceSemanticHash']==original['semanticHash']
   assert p['choices']==new['choices'] and p['preservedCorrectChoice']==next(c for c in original['choices']if c['choiceId']==original['answerChoiceId'])
  else:assert old==new
  check=pairby[new['problemId']];assert check['mathematicalPairCount']in [0,None],new['problemId']
  if check['status']=='complete-exact-mathematical-pair-review':
   vals=[parse(c['math'])for c in new['choices']]
   if isinstance(vals[0],s.Tuple):
    certs=[]
    for i,j in itertools.combinations(range(4),2):
     coordinates=[];found=False
     for axis,(u,v)in enumerate(zip(vals[i],vals[j])):
      if u==v:coordinates.append({'coordinate':axis,'equal':True,'exactValue':s.srepr(u)});continue
      eq,cert=scalar_sum(u,-v);coordinates.append({'coordinate':axis,'equal':eq,**cert});found|=not eq
     assert found;certs.append({'indices':[i,j],'coordinates':coordinates,'distinct':True})
    tupleChecks.append({'problemId':new['problemId'],'familyId':new['familyId'],'sixPairCertificates':certs})
   if new['familyId'].endswith('telescoping-arctan'):
    ns=[normalized_tangent(v)for v in vals];assert len({q for q,_ in ns})==4
    beforeVals=[parse(c['math'])for c in old['choices']];prior=[normalized_tangent(v)[0]for v in beforeVals];dups=[[i,j]for i,j in itertools.combinations(range(4),2)if prior[i]==prior[j]]
    atanChecks.append({'problemId':new['problemId'],'sourceInstance':original['parameters']['instance'],'literalChoiceNormalizations':[e for _,e in ns],'allFourDistinctAfter':True,'priorDuplicateIndices':dups,'scope':'Rational tangent products and explicit(0,pi/2) angle bounds establish the same principal value exactly. A CAS failure to simplify was not used as non-equivalence evidence.'})
  joins.append({'problemId':old['problemId'],'familyId':old['familyId'],'sourceCanonicalRawSHA256':H(original),'sourceContentHash':original['contentHash'],'sourceSemanticHash':original['semanticHash'],'beforeOptionInputSHA256':H(old),'proposedOptionInputSHA256':H(new),'patchSHA256':H(p)if p else None,'patchVersion':p['patchVersion']if p else None,'genericParserPreviouslyUnsupported':old['problemId']in previousUnsupported,'resolutionStatus':check['status'],'mathPairCount':check['mathematicalPairCount'],'correctRank':rankby.get(old['problemId'],{}).get('correctRank'),'admitted':False})
 assert len(joins)==705 and len(tupleChecks)==9 and len(atanChecks)==10
 pendingSupports={f:r for f,r in ranks['families'].items()if r['records']>=8 and len(r['correctRanks'])<=2 and f!='m3-series-easy-ratio-test-data'}
 FLAGS={
 'm3-series-easy-binomial-total':'The correct value is2^n, so square status alternates with parity. This is intrinsic to the binomial identity. An odd-index counterexample has correct32 and wrong16, so the bare square rule fails. Wrong endpoint/normalization values supply both square and nonsquare alternatives; the ten canonical integer values are listed in the source. The measured45%/65% split is retained, not described as proof that all form cues are absent.',
 'm3-series-medium-weighted-binomial-total':'The answer n*2^(n−1) has a genuine divisibility consequence of the derivative-binomial identity. Wrong alternatives such as2^n and twice the answer also share that divisibility. Each flagged rule makes only two unique heldout predictions, with the remainder tied or inapplicable. The rule is a useful partial mathematical filter in some cases; it does not uniquely identify the complete family.',
 'm3-series-olympiad-Fourier-fourth-sine':'Every finite menu has at least two pure pi-squared rational-coefficient alternatives, so that expression class does not isolate the answer. Canonical simplification of special-angle first terms creates shorter rational distractors in some cases and longer trigonometric distractors in others. The length-min25%/75% split is preserved. Only two heldout predictions are unique; neither formatting padding nor unsimplified constants is introduced to tune lengths.',
 'm3-series-olympiad-totient-Lambert':'The correct answer remains among the upper two actual values in all eight menus. Positivity and divisor-count identities give some legitimate lower bounds, but the authored pool also has a persistent rank restriction. This remains an explicit additional rank-support finding for parent disposition, not a blanket clearance.',
 'm3-series-easy-ratio-test-data':'The literal factorial-ratio tasks have the two genuine outcomes0 and positive infinity, five each. Thus the extreme-two rule scores50% after uniform tie-breaking. Finite alternatives1 and the displayed exponential coefficient are the exact errors from omitting the factorial shift. Length and noninteger-form features identify the infinity symbol; their heldout bias reflects which growth direction fell in the fixed split. Altering this support would require changing mathematical task forms, not cosmetically padding the infinity notation.'}
 position='The flag concerns one deterministic diagnostic shuffle, including any replicated split score; the actual selector applies a fresh choice shuffle and computes the correct index from the preserved choice ID. The copied selector source is evidence. This is not used to excuse expression-form or magnitude flags, which receive separate dispositions.'
 families=[]
 for f,g in screen['families'].items():
  rr=ranks['families'].get(f);sub=[j for j in joins if j['familyId']==f];flags=[]
  for flag in g['flags']:
   result=next(x for x in g['results']if x['rule']==flag['rule']);reason=position if flag['rule'].startswith('shuffled-position-')else FLAGS.get(f,'This flag remains a parent disposition requirement; no generic nonreplication-only clearance is asserted.')
   flags.append({'rule':flag['rule'],'training':result['training'],'heldout':result['heldout'],'disposition':'fresh-production-shuffle-distinct-from-fixed-audit-permutation'if flag['rule'].startswith('shuffled-position-')else'additional-rank-support-finding'if f in pendingSupports else'bounded-editorial-disposition-with-measured-residual','reason':reason})
  categorical=all(x['resolutionStatus']=='not-applicable-categorical'for x in sub)
  families.append({'familyId':f,'records':len(sub),'literalPairCoverage':{'numericOrTuple':sum(x['resolutionStatus']!='not-applicable-categorical'for x in sub),'categoricalNotApplicable':sum(x['resolutionStatus']=='not-applicable-categorical'for x in sub),'unresolved':0},'scalarRankDiagnostic':rr,'allFlagDispositions':flags,'smallSampleDisposition':'One finite item has no meaningful within-family train/heldout estimate. Mathematical checks apply to this item; do not extrapolate a family-wide cue rate.'if len(sub)<6 else'Finite small-family scores are diagnostic rather than statistical guarantees.','additionalRankSupportReviewPending':f in pendingSupports,'categoricalScope':'These are literal logical classifications with no additive inverse; categorical wording/format remains covered by the separate root feature screen.'if categorical else None,'hasProposedAmendment':any(x['patchSHA256']for x in sub),'admission':'not performed'})
 forms=[]
 for form,g in screen['answerForms'].items():
  flags=[]
  for fl in g['flags']:
   q=next(q for q in g['results']if q['rule']==fl['rule']);flags.append({'rule':fl['rule'],'training':q['training'],'heldout':q['heldout'],'disposition':'genuine-extended-real-outcomes-with-form-specific-limitation'if form=='extended-real'else'parent-review-required','reason':FLAGS['m3-series-easy-ratio-test-data']if form=='extended-real'else'No pooled answer-form aggregate is used to clear a flagged family.'})
  forms.append({'answerForm':form,'records':g['items'],'allFlagDispositions':flags,'scope':'The pooled answer form cannot override any per-family flag or rank-support finding.'})
 unresolved=[{'familyId':f,'records':r['records'],'correctRanks':r['correctRanks'],'twoChoiceExpectedTieBrokenAccuracy':0.5,'meaning':'All observed answers fall in this two-rank support. This is a bounded additional diagnostic, not100% answer prediction. The relevant source pool and mathematical bounds need parent disposition; no claim of final admission clearance.'}for f,r in pendingSupports.items()]
 unsupported=[j for j in joins if j['genericParserPreviouslyUnsupported']];assert len(unsupported)==143;assert not pendingSupports
 report={'status':'complete-bounded705-supplemental-review-pending-final76-parent-review','inputSHA256':sha(source),'proposedInputSHA256':sha(final),'initialGenericDiagnosticSHA256':sha(BASE/'root-mathematical-opposite-input.json'),'records':705,'families':families,'answerForms':forms,'counts':{'families':len(families),'proposedPatches':162,'independentlyParentReviewedPatches':86,'patchesAwaitingParentReview':76,'numericOrTuplePairReviewed':651,'scalarMenusWithSixExactInequalities':642,'tupleMenusWithSixExactInequalities':9,'categoricalMenusNotApplicableToArithmeticPairRule':54,'numericPairCertificates':3906,'numericChoiceInequalityCertificates':3906,'mathematicalOppositePairsAfter':sum(len(x['oppositePairs'])for x in pairs['recordsEvidence']),'unresolvedPairParses':0,'previousGenericUnsupported':143,'previousUnsupportedNowNumericOrTuple':sum(j['resolutionStatus']!='not-applicable-categorical'for j in unsupported),'previousUnsupportedNowExplicitCategorical':sum(j['resolutionStatus']=='not-applicable-categorical'for j in unsupported),'remainingTwoRankSupportFamilies':len(unresolved)},'rootUnsupportedResolution':unsupported,'additionalRankSupportFindings':unresolved,'recommendedDifficultyChanges':[{'problemId':p['problemId'],'familyId':p['familyId'],'index':p['instanceIndex'],'recommendedDifficulty':p.get('recommendedDifficulty'),'reason':p.get('difficultyNote')}for p in patches.values()if p.get('recommendedDifficulty')=='medium'and full[p['problemId']]['difficulty']=='hard'],'sourceJoins':joins,'atanFullFamilyReview':atanChecks,'tupleInequalityReview':tupleChecks,'successfulPractices':['A failed symbolic simplification cannot establish inequality. Exact arctangent difference/tangent identities must include a branch interval; this exposed and repaired two equivalent wrong choices.','Check the domain defined in the question for every option, including intentionally wrong answers. Two negative-Gamma inputs exceeded the displayed definition.','Audit predeclared unions of numeric ranks as well as single ranks. The middle-two predictor is50% when all answers are in that subset, not100%; inspect the source pool before calling it structural.','Treat unsupported parsing as work to resolve, with exact per-literal certificates or an explicit categorical scope. A pooled accuracy cannot clear an unsupported family.','Freeze candidate revisions and independent review bindings separately; preserve failed drafts and the original bank.'],'limitations':['This is a bounded review of mathematical opposite pairs, literal distinctness, scalar ranks and all flags in the copied finite root screen. It is not an unbounded search over every possible learned classifier.','The root-independent76-row final amendment review is pending. The earlier6 and80 amendments passed separate parent review. This remains a bounded common-form diagnostic, not a guarantee against every possible learned classifier or admission.','All statements, exact answers and explanations are preserved; this task does not reprove every source question from scratch. Existing mathematical review scope stays separate.','The old705 and455 passes are preserved as narrower previous checks. They did not establish the new arctangent equivalence or combined-rank conditions.','No human review, formal proof, registry change, horizon seed rerun, production import or publication occurred.'],'humanReviewed':False,'formalProof':False,'admitted':False}
 (BASE/'complete705-final-review.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');print(json.dumps(report['counts']))
if __name__=='__main__':main()
